import { Tooltip } from "antd";
import { useEffect, useState } from "react";
import { FaLocationDot } from "react-icons/fa6";
import { useNavigate, useParams } from "react-router-dom";
import Layout from "../../components/global/layout";
import ApiClient from "../../methods/api/apiClient";
import loader from "../../methods/loader";
import shared from "./shared";
import { MdCategory } from "react-icons/md";

const View = () => {
  const [data, setData] = useState();
  const history = useNavigate();
  const { id } = useParams();

  useEffect(() => {
    getDetail();
  }, []);

  const getDetail = () => {
    loader(true);
    ApiClient.get(shared.detailApi, { id: id }).then((res) => {
      loader(false);
      if (res.success) {
        setData(res.review);
      }
    });
  };

  return (
    <>
      <Layout>
        <div className="flex items-center mb-8">
          <Tooltip placement="top" title="Back">
            <span
              onClick={() => history(-1)}
              className="!px-4  py-2 flex items-center justify-center bg-[#976DD0] text-white rounded-lg shadow-btn hover:bg-[#976DD0] border transition-all  mr-3"
            >
              <i className="fa fa-angle-left text-lg"></i>
            </span>
          </Tooltip>
          <div>
            <h3 className="text-lg lg:text-2xl font-semibold text-[#111827]">
              {shared.addTitle} Details
            </h3>
          </div>
        </div>
        <div className="wrapper_section">
          <div className="grid grid-cols-12 gap-6">
            <div className="col-span-12">
              <div className="  shadow-box overflow-hidden rounded-lg bg-white  gap-4 shrink-0 ">
                <h4 className="p-4 border-b  font-medium rounded-[5px] rounded-bl-[0] rounded-br-[0] flex items-center text-[#976DD0] ">
                  <div className=" me-3 bg-[#996dca21] p-3 rounded-md">
                  <MdCategory className="text-[18px]" />
                  </div>
                  Category Information
                </h4>
                <div className="grid grid-cols-12 gap-5 p-4">
                  <div className="col-span-6 flex flex-col">
                    <label className="font-medium text-md  text-[#676767] mb-1 block">
                      Reviewer Name
                    </label>
                    <p className="text-sm font-normal">{data && data?.reviewerName || "--"}</p>
                  </div>
                  <div className="col-span-6 flex flex-col">
                    <label className="font-medium text-md  text-[#676767] mb-1 block">
                    Source 
                    </label>
                    <p className="text-sm font-normal">{data && data?.source || "--"}</p>
                  </div>
                  <div className="col-span-6 flex flex-col">
                    <label className="font-medium text-md  text-[#676767] mb-1 block">
                      Stars
                    </label>
                    <p className="text-sm font-normal">
                      {data?.stars || 0}
                    </p>
                  </div>
                   <div className="col-span-6 flex flex-col">
                    <label className="font-medium text-md  text-[#676767] mb-1 block">
                      Agency
                    </label>
                    <p className="text-sm font-normal">
                      {data?.agencyId?.fullName || "--"}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </Layout>
    </>
  );
};

export default View;
